completionCheck.command:
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
const packet='docs/reviews/admission-lifetime-assurance-r4';
const dir=packet+'/records/2026-10-16-060526-admission-clarity';
const read=p=>JSON.parse(fs.readFileSync(p));
const sha=p=>createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const reviewed='d1632ef02acd34c0460426185242174f7896a463';
const paths=execFileSync('git',['ls-tree','-r','--name-only',reviewed,'--',packet],{encoding:'utf8'}).trim().split('\n');
for(const p of paths)assert.ok(fs.readFileSync(p).equals(execFileSync('git',['show',reviewed+':'+p])),p);
const rawPaths=[];
function walk(p){for(const e of fs.readdirSync(p,{withFileTypes:true})){const f=path.join(p,e.name);if(e.isDirectory())walk(f);else rawPaths.push(f);}}
walk(packet+'/records');walk(packet+'/register');
rawPaths.push(packet+'/reader-m42-g-events.jsonl',packet+'/reader-x19-g-events.jsonl');
const credential=process.env.LITELLM_NETBIRD_API_KEY;
assert.ok(credential);
const secretMatches=rawPaths.filter(p=>fs.readFileSync(p).includes(Buffer.from(credential)));
assert.equal(secretMatches.length,0,'Credential literal must not appear in retained records');
const record=read(dir+'/run.json'),accounting=read(dir+'/ADMISSION-ACCOUNTING.json'),replay=read(dir+'/admission-judge-replay.json'),tallyReplay=read(dir+'/admission-replay.json'),receipt=read(packet+'/records/admission-execution-receipt.json');
assert.equal(receipt.reviewedRevision,reviewed);
assert.equal(receipt.readiness.sha256,sha(packet+'/admission-provider-readiness-06.txt'));
assert.equal(record.end,'completed');assert.equal(accounting.complete,true);assert.deepEqual(accounting.issues,[]);assert.deepEqual(replay.issues,[]);
const hashNow=['RESULT.json','RESULT.md'].map(name=>sha(dir+'/'+name));
assert.deepEqual(tallyReplay.tallyHashes,hashNow);assert.equal(tallyReplay.identical,true);
assert.equal(sha('/home/apnex/.config/opencode/opencode.json'),'3d50767fea0cf4305e62d9baeca99edf7d1fa14281eebb320084cffd2d9e7f64');
const cells=record.cells.map(id=>read(dir+'/cells/'+id+'.json'));
const ended=cells.filter(c=>c.attempts.at(-1).validity.cause==='behaviour').map(c=>({cell:c.cell,attempts:c.attempts.length,validity:c.attempts.at(-1).validity,answerFile:c.scoredFile.content,eventPath:c.attempts.at(-1).outcome.events}));
for(const c of ended) assert.ok(fs.readFileSync(c.eventPath).equals(fs.readFileSync(packet+'/reader-'+c.cell.split('.')[1]+'-g-events.jsonl')));
console.log(JSON.stringify({observedAt:new Date().toISOString(),reviewedRevision:reviewed,frozenFilesUnchanged:paths.length,run:record.run,states:record.states,end:record.end,readerProfilesPassed:record.probes.filter(p=>p.pass).length,judgeProfilesPassed:record.judgeProbes.filter(p=>p.pass).length,readerAttempts:cells.reduce((n,c)=>n+c.attempts.length,0),usableValidPhases:cells.filter(c=>c.valid).length,endedPhases:ended,accounting:{complete:accounting.complete,issues:accounting.issues,outcomes:accounting.outcomeCount,intendedSlots:accounting.intendedVoteSlots,castVotes:accounting.castVotes,explicitUncastSlots:accounting.rows.flatMap(r=>r.slots).filter(s=>s.status==='uncast').length,numericConditions:accounting.numericConditions,mechanicalDisposition:accounting.mechanicalDisposition,regressedControls:accounting.table.filter(r=>r.control&&r.candidateSum<r.predecessorSum).map(r=>r.heading)},judgeReplay:{issues:replay.issues,retainedJobs:replay.retainedJobs,reconciledJobs:replay.reconciledJobs,replayedReplies:replay.replayedReplies,modelCalls:replay.modelCalls},tallyReplay,retainedFiles:rawPaths.length,retainedBytes:rawPaths.reduce((n,p)=>n+fs.statSync(p).size,0),credentialLiteralMatches:secretMatches.length,sharedOperatorConfigUnchanged:true,hashes:Object.fromEntries(rawPaths.sort().map(p=>[p.slice(packet.length+1),sha(p)])),scope:'Author execution/accounting evidence; no independent assurance verdict'},null,2));
NODE

slotCensusCorrection.command:
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import fs from 'node:fs';
const a=JSON.parse(fs.readFileSync('docs/reviews/admission-lifetime-assurance-r4/records/2026-10-16-060526-admission-clarity/ADMISSION-ACCOUNTING.json'));
const statuses={};
for(const slot of a.rows.flatMap(r=>r.slots)) statuses[slot.status]=(statuses[slot.status]??0)+1;
assert.equal(statuses['not cast: ended phase'],96);
assert.equal(a.castVotes,192);
assert.equal(Object.values(statuses).reduce((n,v)=>n+v,0),288);
console.log(JSON.stringify({recordedAt:new Date().toISOString(),statuses,castVotes:a.castVotes,explicitUncastSlots:statuses['not cast: ended phase'],totalSlots:288,correction:'The first supplemental author diagnostic counted status === uncast, a value not used by this schema, and printed zero. This direct status census corrects that diagnostic; no run record, score or accounting artifact was edited.'},null,2));
NODE

